function board(host){const s=new THREE.Shape();s.moveTo(-9.7,-23);s.lineTo(-8.9,-23.8);s.lineTo(8.9,-23.8);s.lineTo(9.7,-23);s.lineTo(9.7,-17);s.absarc(9.7,-13.95,3.05,-Math.PI/2,Math.PI/2,true);s.lineTo(9.7,20.7);s.lineTo(8.6,21.8);s.lineTo(4.1,21.8);s.lineTo(3.2,20.9);s.lineTo(-3.2,20.9);s.lineTo(-4.1,21.8);s.lineTo(-8.6,21.8);s.lineTo(-9.7,20.7);s.lineTo(-9.7,-10.9);s.absarc(-9.7,-13.95,3.05,Math.PI/2,-Math.PI/2,true);s.closePath();hole(s,0,-13.5,1.35);const solder=[];for(let i=0;i<4;i++){hole(s,8.75,-18.3-i*1.3,.36);solder.push([8.75,-18.3-i*1.3]);}const pcb=solid(host.body,s,.8,[0,0,0],plastic(0x252e29),'UnitV2 own-photo populated main PCB with real reliefs and retaining bore');const lands=[];for(const[x,y]of solder)lands.push(annulus(host.body,.55,.36,.03,[x,y,.81],metal(0xc4ae70),'UnitV2 four real reserved plated pads'));lands.push(annulus(host.body,1.8,1.35,.04,[0,-13.5,.81],metal(),'UnitV2 true mounting-hole plated rim'));return{pcb,lands};}
function circuit(host){const g=frame(host.body,'UnitV2 concealed PCB packages;footprints and positions appearance-derived'),dark=plastic(0x1d201d),tin=metal(),ceramic=plastic(0xb3a17b),packs=[];const chip=(n,at,size)=>{const p=box(g,size,at,dark,'UnitV2 '+n+' physical package envelope');p.userData={role:'concealed-package',placementInferred:true};packs.push(p);return p;};const soc=chip('SSD202D',[0,5,-1],[11,11,2]),ram=chip('128MB DDR3',[-5.6,-5,-.8],[5.5,7.6,1.6]),nand=chip('NAND;official capacity conflict',[4.9,-5,-.8],[5.4,7.8,1.6]);chip('RTL8188FTV Wi-Fi',[5.6,17,1.25],[4.2,4.2,.9]);chip('camera interface package',[-4.5,4.5,4.1],[2.3,4.2,1.0]);const clock=box(g,[5.7,2.5,1.2],[-6.7,19.3,1.4],tin,'UnitV2 own-photo metal crystal package');clock.rotation.z=-Math.PI/4;
 for(let i=0;i<26;i++){const x=(i%2?1:-1)*(7.7-(i%3)*.35),y=18-Math.floor(i/2)*2.1;if(x<2&&y>1.4&&y<14.8)continue;box(g,[1.3,.7,.5],[x,y,1.05],i%3?ceramic:dark,'UnitV2 visible passive package');for(const dx of[-.55,.55])box(g,[.23,.7,.53],[x+dx,y,1.05],tin,'UnitV2 passive metal termination');}
 const fpc=frame(g,'UnitV2 retained camera flexible-board socket',[0,-7.2,1.9]);box(fpc,[10.4,3.7,2.2],[0,0,0],plastic(0xe3e3d8),'UnitV2 white camera FPC carrier');box(fpc,[8.8,.9,.5],[0,1.2,1.3],dark,'UnitV2 actual camera FPC latch');for(let i=0;i<24;i++)box(fpc,[.18,1,.09],[(i-11.5)*.35,-1.3,-1.05],tin,'UnitV2 camera FPC physical terminal');const switchBase=box(g,[4.8,2.1,4.1],[0,20.7,2.8],dark,'UnitV2 top fixed user switch envelope'),follower=box(g,[2.9,1.0,1.3],[0,22.0,2.7],plastic(0xc5c6bd),'UnitV2 retained top switch follower');const heatsink=box(g,[13.4,20.3,1.1],[0,3,-3.0],metal(0x5f6360),'UnitV2 concealed fixed heat spreader appearance envelope');for(let i=0;i<9;i++)box(g,[.8,19.8,1.1],[(i-4)*1.45,3,-4.05],metal(0x5f6360),'UnitV2 concealed fixed heat-spreader fin');return{group:g,packs,soc,ram,nand,clock,fpc,switchBase,follower,heatsink};}
function optics(host){const flexShape=roundedRect(13.7,16.8,.5);const flex=solid(host.body,flexShape,.14,[0,9.3,3.45],plastic(0xb58c25),'UnitV2 retained amber GC2145 camera flexible PCB');const ribbon=box(host.body,[6.5,8.5,.13],[0,-2.5,3.3],plastic(0xb58c25),'UnitV2 camera attached FPC ribbon');for(let i=0;i<20;i++)box(host.body,[.1,8.2,.025],[(i-9.5)*.28,-2.5,3.38],metal(0xc19d48),'UnitV2 camera ribbon real copper appearance');box(host.body,[10.0,10,1.6],[0,11.9,4.35],plastic(0x131714),'UnitV2 GC2145 fixed square lens mount');const barrel=annulus(host.body,4.37,2.55,3.45,[0,11.9,5.4],plastic(0x101512),'UnitV2 fixed threaded lens barrel with real optical bore');const sensor=box(host.body,[4.7,4.7,.5],[0,11.9,5.5],plastic(0x193a37),'UnitV2 physical GC2145 imaging package behind lens');const glass=mesh(host.body,new THREE.SphereGeometry(2.45,40,24),plastic(0x274d4d),[0,11.9,8.7],'UnitV2 retained curved lens glass');glass.scale.z=.12;const innerGlass=mesh(host.body,new THREE.CylinderGeometry(1.45,1.45,.2,48).rotateX(Math.PI/2),plastic(0x3f6964),[0,11.9,8.98],'UnitV2 fixed central optical coating');
 const micshape=roundedRect(3.8,4.6,.25);hole(micshape,0,.6,.28);const microphone=solid(host.body,micshape,1.7,[8,11.5,3.5],metal(0xaeb1a9),'UnitV2 actual offset top-ported metal microphone can');box(host.body,[3.3,4.1,.15],[8,11.5,3.48],plastic(),'UnitV2 microphone retained internal carrier');const camera=host.add(new Component({id:'camera',label:'Fixed GC2145 optical anchor',position:spec.camera.position,meta:{role:'passive-optical-anchor',sensor:'GC2145',fovDeg:68,scope:'Geometry and outward optical axis only;no framebuffer,frames,capture,AI results,video,USB-camera simulation or invented readings.'}})),mic=host.add(new Component({id:'microphone',label:'Fixed microphone acoustic anchor',position:spec.microphone.position,meta:{role:'passive-acoustic-anchor',scope:'Physical can and acoustic location only;no sampling,audio buffers,sound level or firmware values.'}}));return{flex,ribbon,barrel,sensor,glass,innerGlass,microphone,camera,mic};}
class FixedLed extends Led{constructor({fixedColor,...rest}){super({...rest,color:fixedColor});this.fixedColor=fixedColor;}set(state){if(typeof state==='boolean')state={on:state};else if(typeof state==='number'||typeof state==='string')state={on:true};return super.set({...state,color:this.fixedColor});}}
function leds(host){const result={};for(const[id,c,x,w,h]of[['red',0xec3035,-1.4,1.4,1.3],['white',0xffffff,1.8,1.8,2.3]]){box(host.body,[w+.2,h+.2,.6],[x,19.4,1.1],plastic(0xd3d2c5),'UnitV2 '+id+' actual PCB indicator carrier');const lens=new THREE.Mesh(new THREE.BoxGeometry(w,h,.35),plastic(c));lens.name='UnitV2 '+id+' real on-board indicator lens';const led=host.add(new FixedLed({id,label:`UnitV2 ${id} indicator`,mesh:lens,fixedColor:c,position:[x,19.4,1.58],glowSize:1.5,meta:{role:'externally-driven-indicator',scope:'Independent fixed-color on/brightness appearance only;no boot,power,fan,camera or network inference.',placementSource:'Own PCB photograph;exact red carrier and PC transmission/light path not dimensioned.No invented shell aperture or light pipe.'}}));result[id]=led;}return result;}
function fan(host){const g=frame(host.body,'UnitV2 actual retained active cooling fan',spec.fan.position),m=plastic(0x1c211e),fixed=annulus(g,6.8,6.1,2.0,[0,0,-1.0],m,'UnitV2 fan fixed annular frame'),motor=mesh(g,new THREE.CylinderGeometry(1.7,1.7,1.8,40).rotateX(Math.PI/2),m,[0,0,-.35],'UnitV2 fan fixed motor carrier');for(const a of[0,Math.PI/2,Math.PI,Math.PI*1.5]){const p=box(g,[.65,4.6,.45],[Math.cos(a)*3.7,Math.sin(a)*3.7,-.85],m,'UnitV2 fixed motor support');p.rotation.z=a-Math.PI/2;}
 const rotor=frame(g,'UnitV2 only actual fan impeller rotates'),hub=mesh(rotor,new THREE.CylinderGeometry(1.9,1.9,.85,40).rotateX(Math.PI/2),plastic(0x252c26),[0,0,.3],'UnitV2 rotating impeller hub'),blades=[];for(let i=0;i<7;i++){const s=new THREE.Shape();s.moveTo(1.5,-.35);s.bezierCurveTo(3.0,-1.7,5.5,-1.5,5.8,-.25);s.bezierCurveTo(4.4,1.35,2.5,1.2,1.5,.4);s.closePath();const blade=solid(rotor,s,.45,[0,0,.03],m,'UnitV2 actual fan blade appearance reconstruction');blade.rotation.z=i*tau/7;blades.push(blade);}const joint=host.add(new VisualJoint({id:'fan',label:'Internal fan impeller · external angle/RPM',axis:[0,0,1],continuous:true,position:spec.fan.position,meta:{demoRpmMax:120,scope:'Only impeller geometry rotates by external angle/RPM.No automatic cooling,temperature,sound,motor/electrical or firmware behavior.',geometrySource:'Product specifies active fan;frame,blade count,clearances and concealed installation are appearance estimates,not a verified fan BOM.'}}));joint.adopt(rotor);return{group:g,fixed,motor,rotor,hub,blades,joint};}
function label(host){const s=new THREE.Shape();s.moveTo(-10.05,13.15);s.lineTo(10.05,13.15);s.lineTo(10.05,-13.15);s.lineTo(6.4,-13.15);s.bezierCurveTo(5.6,-11.4,4.7,-8.8,0,-8.6);s.bezierCurveTo(-4.7,-8.8,-5.6,-11.4,-6.4,-13.15);s.lineTo(-10.05,-13.15);s.closePath();const film=solid(host.body,s,.035,[0,0,0],plastic(0xf5f4eb),'UnitV2 real rear die-cut adhesive film;physical support retained without ink');film.position.fromArray(spec.label.position);film.quaternion.copy(FACE.back);const ink=printedArtwork(host,{target:film,url:new URL('./artwork/rear.png',import.meta.url).href,size:spec.label.size,position:[0,4.2,-9.12],face:'back',depth:.09,name:'UnitV2 own-photo accurate rear information label redraw',artworkKind:'official-photo-code-redraw'});return{film,ink};}
export function buildUnitV2(host,options=host.options){const opts={...spec.options,...options};if(!['none','stand','brick'].includes(opts.mount))throw new RangeError('UnitV2 mount must be none,stand or brick');if(typeof opts.card!=='boolean'||typeof opts.usbCable!=='boolean')throw new TypeError('UnitV2 card/usbCable must be boolean');const parts=addCadParts(host,data,{shell:plastic(0x269ed0)}),front=parts[data[0].name],back=parts[data[1].name],pcb=board(host),electronics=circuit(host),input=grove(host),usbc=usb(host),storage=sd(host),optical=optics(host),indicators=leds(host),cooling=fan(host),user=host.add(new NativeButton(front));user.follower=electronics.follower;user.followerRest=electronics.follower.position.y;const mount=host.add(new Port({id:'mount',label:'UnitV2 own four-clip mount',connector:spec.mount.connector,position:spec.mount.position,quaternion:portQuaternion('back'),hitSize:[26.7,1,28],meta:{role:'visual-connector',face:'back',scope:'Own U078-D Stand/Back-Brick mechanical attachment only;not generic HAT,LEGO compatibility or an electrical port.',datumSource:'Exact native side slots at y≈16/-4;clip inner clearance16.43mm and carrier dimensions from own drawings.'}}));const labels=label(host);host.unitV2Assembly={parts,front,back,pcb,electronics,input,usbc,storage,optical,indicators,cooling,user,mount,labels,options:opts};host.unitStickers=labels.ink??[];if(opts.card)storage.port.attach(MicroSdCard);if(opts.usbCable)usbc.port.attach(UsbCable);if(opts.mount==='stand')mount.attach(Stand);else if(opts.mount==='brick')mount.attach(BackBrick);}
